prog='''from collections import Counter, defaultdict, deque

def _components(g, bg):
    h, w = len(g), len(g[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == bg or (r, c) in seen:
                continue
            color = g[r][c]
            q = [(r, c)]
            seen.add((r, c))
            pts = []
            while q:
                y, x = q.pop()
                pts.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and g[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            out.append((color, pts))
    return out

