    y0 = min(y for y,x in pts); x0 = min(x for y,x in pts)
    return tuple(sorted((y-y0, x-x0) for y,x in pts))

def _l_corner(pts):
    # Return the corner and vertical-arm direction for a component that is exactly
    # the union of one solid horizontal and one solid vertical segment.
    ys = [y for y,x in pts]; xs = [x for y,x in pts]
    y0,y1,x0,x1 = min(ys),max(ys),min(xs),max(xs)
    S = set(pts)
    for cy in (y0,y1):
        for cx in (x0,x1):
            horiz = {(cy,x) for x in range(x0,x1+1)}
            vert = {(y,cx) for y in range(y0,y1+1)}
            if S == horiz | vert:
                dy = 1 if y1 > cy else -1
                return (cy,cx,dy)
    return None

def transform(grid):
    g = [row[:] for row in grid]
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    comps = _components(g, bg)

    # A long 9-colored L is the recoloring guide. Find repeated objects and
    # recolor the instance across the horizontal arm, opposite the vertical arm.
    guide = None
    for color, pts in comps:
        if color == 9:
            corner = _l_corner(pts)
            if corner and len(pts) >= 6:
                if guide is None or len(pts) > len(guide[1]):
                    guide = (corner, pts)
    if guide:
