            _, items = max(choices, key=lambda z:z[0])
            target_side = -1 if vertical_dir > 0 else 1
            for color, pts in items:
                center_y = sum(y for y,x in pts)/len(pts)
                if (target_side < 0 and center_y < cy) or (target_side > 0 and center_y > cy):
                    for y,x in pts: g[y][x] = 9
        return g

    # In the variant with a large non-9 L and small 9 corner marks, recolor
